/*
 * A274024  a(n) is the number of distinct residues generated by the
 *          recurrence b(k+1,n) = 2^b(k,n) (mod n), k = 1,2,...,n. The initial
 *          value is b(1,n) = 1.
 * https://oeis.org/A274024
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = number of distinct residues generated by b(1,n)=1,
 *            b(k+1,n)=2^b(k,n) (mod n) until the first repetition
 * Range:     u8 n <= 419, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   mod_pow
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include <stdlib.h>
#include <stdbool.h>
#include "../utils/mod_pow.h"

/* n is an unsigned 64‑bit index type, seq_t is an unsigned integer type
   (possibly arbitrary precision).  The implementation uses a boolean
   array of length n to count distinct residues.  For n==1 the sequence
   contains the values 1 and 0, so a(1)=2. */
seq_t a(idx_t n)
{
    /* Handle the special case n == 1 directly. */
    if (n == 1)
        return (seq_t)2;

    /* Allocate an array that marks which residues have been seen. */
    bool *seen = (bool *)calloc((size_t)n, sizeof(bool));
    if (!seen)
        return 0;          /* out‑of‑memory → return 0 (not expected) */

    idx_t  idx_init = 1;                     /* 1 < n for n > 1 */
    bool   *p_seen  = seen + idx_init;       /* helper pointer */
    *p_seen = true;                          /* mark 1 as seen          */
    seq_t  distinct = 1;                     /* count of distinct values*/
    seq_t  val = 1;                           /* current residue        */

    while (1) {
        /* next value: 2^val mod n   (val ≤ n‑1 < 2^64) */
        val = mod_pow((seq_t)2, (uint64_t)val, (seq_t)n);

        /* index into the seen array */
        idx_t idx = (idx_t)val;               /* val fits into 64 bits */
        bool *p = seen + idx;

        if (!*p) {
            *p = true;          /* mark new residue            */
            ++distinct;         /* count it                   */
        } else {
            break;              /* cycle detected             */
        }
    }

    free(seen);
    return distinct;
}
